/**
 * Clip media for the timeline: the filmstrip sprite index (`thumbs.json`) and audio peaks
 * (`waveform.json`) generated by the host. Each is fetched once per asset and shared by
 * every clip of that asset; waveforms get lazily built min/max mip levels so drawing costs
 * O(visible pixels) at any zoom.
 */
import type { Clip } from '@reelforge/core'
import { useCallback, useSyncExternalStore } from 'react'
import { api } from '@/api/index.ts'

/** Layout of the host's `thumbs.jpg` sprite (times in µs). */
export interface ThumbsIndex {
  /** Tile i shows source time i × interval. */
  interval: number
  columns: number
  rows: number
  tileWidth: number
  tileHeight: number
  count: number
}

/** `waveform.json`: interleaved int8 [min, max] peaks per `bucketUs` of source. */
export interface WaveformData {
  bucketUs: number
  count: number
  peaks: number[]
}

/** Decoded waveform with lazily built mip levels (level k aggregates 2^k buckets). */
export interface Waveform {
  bucketUs: number
  levels: Int8Array[]
}

/* ------------------------------------------------------------------ resource cache */

type Entry<T> =
  | { status: 'loading'; listeners: Set<() => void> }
  | { status: 'ready'; value: T; listeners: Set<() => void> }

export interface MediaLoader {
  thumbs(assetId: string): Promise<ThumbsIndex>
  waveform(assetId: string): Promise<WaveformData>
}

const enc = encodeURIComponent

let loader: MediaLoader = {
  thumbs: (id) => api.request<ThumbsIndex>('GET', `/api/assets/${enc(id)}/thumbs.json`),
  waveform: (id) => api.request<WaveformData>('GET', `/api/assets/${enc(id)}/waveform.json`),
}

const thumbsCache = new Map<string, Entry<ThumbsIndex>>()
const waveCache = new Map<string, Entry<Waveform>>()

/** Replaces the loader (tests) and clears the caches. Returns a restore function. */
export const setMediaLoader = (next: MediaLoader): (() => void) => {
  const prev = loader
  loader = next
  thumbsCache.clear()
  waveCache.clear()
  return () => {
    loader = prev
    thumbsCache.clear()
    waveCache.clear()
  }
}

const load = <T, R>(
  cache: Map<string, Entry<T>>,
  key: string,
  fetcher: () => Promise<R>,
  decode: (r: R) => T,
): Entry<T> => {
  const hit = cache.get(key)
  if (hit) return hit
  const entry: Entry<T> = { status: 'loading', listeners: new Set() }
  cache.set(key, entry)
  fetcher().then(
    (r) => {
      const ready: Entry<T> = { status: 'ready', value: decode(r), listeners: entry.listeners }
      cache.set(key, ready)
      for (const l of entry.listeners) l()
    },
    () => {
      // Missing/failed derivatives are cosmetic: drop the entry so a later mount retries.
      cache.delete(key)
      for (const l of entry.listeners) l()
    },
  )
  return entry
}

const useResource = <T, R>(
  cache: Map<string, Entry<T>>,
  key: string | undefined,
  fetcher: (key: string) => Promise<R>,
  decode: (r: R) => T,
): T | null => {
  // Stable per key so React does not resubscribe on every render.
  const subscribe = useCallback(
    (cb: () => void) => {
      if (!key) return () => undefined
      const e = load(cache, key, () => fetcher(key), decode)
      e.listeners.add(cb)
      return () => {
        e.listeners.delete(cb)
        cache.get(key)?.listeners.delete(cb)
      }
    },
    [cache, key, fetcher, decode],
  )
  const snapshot = () => {
    if (!key) return null
    const e = cache.get(key)
    return e?.status === 'ready' ? e.value : null
  }
  return useSyncExternalStore(subscribe, snapshot, snapshot)
}

const identity = <T>(x: T): T => x
// Module-level so hook dependencies stay stable; they read the current `loader`.
const fetchThumbs = (id: string) => loader.thumbs(id)
const fetchWaveform = (id: string) => loader.waveform(id)

/** Sprite index for an asset once its thumbnails are ready (null while loading/absent). */
export const useThumbsIndex = (assetId: string | undefined, ready: boolean): ThumbsIndex | null =>
  useResource(thumbsCache, ready ? assetId : undefined, fetchThumbs, identity)

/** Decoded waveform for an asset once it is ready (null while loading/absent). */
export const useWaveform = (assetId: string | undefined, ready: boolean): Waveform | null =>
  useResource(waveCache, ready ? assetId : undefined, fetchWaveform, decodeWaveform)

/* ------------------------------------------------------------------ waveform */

export const decodeWaveform = (w: WaveformData): Waveform => ({
  bucketUs: w.bucketUs,
  levels: [Int8Array.from(w.peaks)],
})

/** Mip level k (built on demand from level k−1: min of mins, max of maxes). */
export const waveLevel = (w: Waveform, k: number): Int8Array => {
  while (w.levels.length <= k) {
    const prev = w.levels[w.levels.length - 1]!
    const pairs = prev.length >> 1
    const out = new Int8Array(Math.ceil(pairs / 2) * 2)
    for (let i = 0, o = 0; i < pairs; i += 2, o += 2) {
      const a = i * 2
      const hasB = i + 1 < pairs
      out[o] = hasB ? Math.min(prev[a]!, prev[a + 2]!) : prev[a]!
      out[o + 1] = hasB ? Math.max(prev[a + 1]!, prev[a + 3]!) : prev[a + 1]!
    }
    w.levels.push(out)
  }
  return w.levels[k]!
}

/** Mip level whose bucket is the largest not exceeding `usPerColumn`. */
export const levelFor = (bucketUs: number, usPerColumn: number): number =>
  usPerColumn <= bucketUs ? 0 : Math.floor(Math.log2(usPerColumn / bucketUs))

export interface WaveDrawOptions {
  /** Canvas size in CSS px. */
  width: number
  height: number
  dpr: number
  /** Source time at canvas x = 0. */
  sourceStart: number
  /** Source µs per CSS px (negative for reversed clips). */
  usPerPx: number
  color: string
}

/**
 * Draws a symmetric peak waveform: one bar per device pixel column, using the mip level
 * that has ≈ one bucket per column so cost is independent of zoom and clip length.
 */
export const drawWaveform = (
  ctx: CanvasRenderingContext2D,
  w: Waveform,
  o: WaveDrawOptions,
): void => {
  const cols = Math.max(0, Math.round(o.width * o.dpr))
  const h = o.height * o.dpr
  ctx.clearRect(0, 0, cols, h)
  ctx.fillStyle = o.color
  const usPerCol = Math.abs(o.usPerPx) / o.dpr
  const k = levelFor(w.bucketUs, usPerCol)
  const level = waveLevel(w, k)
  const bucket = w.bucketUs * 2 ** k
  const n = level.length >> 1
  const mid = h / 2
  const scale = (h / 2 - 0.5) / 128
  for (let x = 0; x < cols; x++) {
    const t0 = o.sourceStart + (x / o.dpr) * o.usPerPx
    const t1 = t0 + o.usPerPx / o.dpr
    let b0 = Math.floor(Math.min(t0, t1) / bucket)
    let b1 = Math.ceil(Math.max(t0, t1) / bucket)
    if (b1 <= 0 || b0 >= n) continue
    b0 = Math.max(0, b0)
    b1 = Math.min(n, Math.max(b0 + 1, b1))
    let amp = 0
    for (let b = b0; b < b1; b++) amp = Math.max(amp, -level[b * 2]!, level[b * 2 + 1]!)
    const bar = Math.max(1, amp * scale)
    ctx.fillRect(x, mid - bar, 1, bar * 2)
  }
}

/* ------------------------------------------------------------------ source mapping */

/**
 * Source time shown at clip-local time `local` (µs from the clip start). Linear in speed;
 * speed ramps are approximated by the base speed, which is plenty for a thumbnail.
 */
export const sourceAt = (clip: Clip, local: number): number => {
  if (clip.type !== 'video' && clip.type !== 'audio') return 0
  const offset = local * clip.speed
  if (clip.type === 'video' && clip.reverse) return clip.in + clip.duration * clip.speed - offset
  return clip.in + offset
}

/* ------------------------------------------------------------------ filmstrip */

export interface TileSlot {
  /** Clip-local x of the slot. */
  x: number
  bgX: number
  bgY: number
}

export interface Filmstrip {
  slotWidth: number
  /** CSS background-size of the sprite at this row height. */
  bgWidth: number
  bgHeight: number
  slots: TileSlot[]
}

/**
 * Filmstrip slots for the visible part [from, to) (clip-local px) of a clip `width` px
 * wide at row `height`. Each slot shows the sprite tile nearest to the source time at its
 * centre; slots outside the range are not produced (virtualised).
 */
export const filmstrip = (
  index: ThumbsIndex,
  clip: Clip,
  ppu: number,
  width: number,
  height: number,
  from: number,
  to: number,
): Filmstrip => {
  const scale = height / index.tileHeight
  const slotWidth = Math.max(8, index.tileWidth * scale)
  const bgWidth = index.columns * slotWidth
  const bgHeight = index.rows * height
  const slots: TileSlot[] = []
  const k0 = Math.max(0, Math.floor(from / slotWidth))
  const k1 = Math.min(Math.ceil(width / slotWidth), Math.ceil(to / slotWidth))
  for (let k = k0; k < k1; k++) {
    const x = k * slotWidth
    const centre = Math.min(x + slotWidth / 2, width)
    const src = sourceAt(clip, centre / ppu)
    const tile = Math.min(index.count - 1, Math.max(0, Math.round(src / index.interval)))
    slots.push({
      x,
      bgX: -(tile % index.columns) * slotWidth,
      bgY: -Math.floor(tile / index.columns) * height,
    })
  }
  return { slotWidth, bgWidth, bgHeight, slots }
}
